  void UpdateStatus(){string team=store.TeamStatus??(store.Teams.Count>0?"Общие проекты на связи":null);sync.Text=(team!=null?team+"  ·  ":"")+(drive.IsConnected?(cloudStatus==""?"Google Диск подключён":cloudStatus):store.Status);}
  async void RunCloudSync(){if(cloudBusy||!drive.IsConnected)return;cloudBusy=true;lastCloud=DateTime.UtcNow;cloudStatus="Синхронизация с Google Диском…";UpdateStatus();try{int epoch=drive.Epoch;var incoming=await drive.PullAsync();if(epoch!=drive.Epoch)return;if(store.MergeRecords(incoming))Refresh();await drive.PushAsync(store.PersonalRecords);cloudStatus="Google Диск · синхронизировано "+DateTime.Now.ToString("HH:mm");}catch(Exception e){cloudStatus="Локально сохранено · "+e.Message;}finally{cloudBusy=false;UpdateStatus();}}
