  void Toast(string text,string action=null,Action onAction=null,double seconds=5){Fx.Toast(toasts,text,action,onAction,seconds);}
  static string Short(string text){return text.Length>38?text.Substring(0,36).TrimEnd()+"…":text;}
  static string Plural(int n,string one,string few,string many){int m=n%100;if(m>=11&&m<=14)return many;m=n%10;return m==1?one:m>=2&&m<=4?few:many;}
