    var off=new MenuItem{Header="Отключить на этом компьютере",Icon=UI.Icon("\uE74D",12,UI.Muted)};off.Click+=delegate{if(MessageBox.Show(this,"Отключить общий проект «"+key+"»? Задачи останутся в папке на сервере, их можно подключить снова.","Ритм",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;try{store.DisconnectTeam(key);if(project==key)project="";Refresh();Toast("Общий проект «"+Short(key)+"» отключён");}catch(Exception e){Error(e);}};menu.Items.Add(off);b.ContextMenu=menu;rail.Children.Add(b);}
