  }
  void ConnectTeam(){var d=new TeamDialog(this,store);if(d.ShowDialog()!=true||d.Result==null)return;person="";Go("board",d.Result.Name);Toast("Общий проект «"+Short(d.Result.Name)+"» подключён. Вы — "+Short(d.Result.User));}
  string DefaultAssignee(string category){if(!store.IsTeamName(category))return null;return person==Mine?store.Me(category):person!=""&&person!=Nobody?person:null;}
  bool MatchesPerson(TaskItem t){return person==""||(person==Mine?store.IsMine(t):person==Nobody?store.IsTeamName(t.category)&&t.assignee==null:Store.SamePerson(t.assignee,person));}
  // Фильтр по людям виден в общем проекте и в общих разделах, если подключён хотя бы один общий проект.
  void UpdatePeopleFilter(){bool team=project!=""?store.IsTeamName(project):view!="today"&&store.Teams.Count>0;people.Visibility=team?Visibility.Visible:Visibility.Collapsed;if(!team){if(person!=Mine)person="";return;}
   var names=store.Members(project==""?null:project);peopleKeys=new List<string>{"",Mine,Nobody}.Concat(names).ToList();if(!peopleKeys.Contains(person))person="";
   people.ItemsSource=new[]{"Все исполнители","Мои задачи","Без исполнителя"}.Concat(names.Select(n=>project!=""&&Store.SamePerson(n,store.Me(project))?n+" (вы)":n)).ToList();people.SelectedIndex=peopleKeys.IndexOf(person);}
  static string Initials(string name){var parts=name.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries);return (parts.Length>1?parts[0].Substring(0,1)+parts[1].Substring(0,1):name.Substring(0,Math.Min(2,name.Length))).ToUpper(ru);}
  static Border Avatar(string name,double size){var t=UI.Text(Initials(name),Math.Round(size*.42),Brushes.White,true);t.HorizontalAlignment=HorizontalAlignment.Center;return new Border{Width=size,Height=size,CornerRadius=new CornerRadius(size/2),Background=UI.B(UI.ColorFor(name)),Child=t,VerticalAlignment=VerticalAlignment.Center};}
  Border PersonChip(TaskItem t){bool mine=store.IsMine(t);var p=new StackPanel{Orientation=Orientation.Horizontal};var a=Avatar(t.assignee,15);a.Margin=new Thickness(0,0,5,0);p.Children.Add(a);p.Children.Add(UI.Text(mine?"Вы":t.assignee,10,mine?UI.B("#A65C3D"):UI.Ink,true));return new Border{Child=p,Background=mine?UI.B("#E9EDE1"):UI.Rail,CornerRadius=new CornerRadius(8),Padding=new Thickness(3,2,8,2),Margin=new Thickness(0,0,6,6),ToolTip="Исполнитель: "+t.assignee+(t.createdBy!=null?"\nСоздал(а): "+t.createdBy:"")};}
