    var cards=new StackPanel{Margin=new Thickness(0,0,4,0)};foreach(var t in entries)cards.Children.Add(TaskCard(t));Grid empty=null;if(entries.Count==0){empty=new Grid{Height=86,Margin=new Thickness(0,0,0,12)};empty.Children.Add(Fx.Dashed());var hint=UI.Text("Перетащите задачу сюда",11,UI.Muted);hint.HorizontalAlignment=HorizontalAlignment.Center;empty.Children.Add(hint);cards.Children.Add(empty);Appear(empty);}cards.Children.Add(QuickAdd(status));dock.Children.Add(new ScrollViewer{Content=cards,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});
