    Border slot=null;Action openSlot=()=>{if(slot!=null||dragTask==null||ghost==null||dragTask.status==status)return;var probe=dragTask.Clone();probe.status=status;probe.completed=status=="done";int index=empty!=null?0:entries.Count(x=>Order(x,probe)<0);var mark=Fx.Dashed();mark.Stroke=UI.Accent;mark.Fill=UI.B("#F0F3EA");mark.Margin=new Thickness(0,0,0,12);slot=new Border{Child=mark,ClipToBounds=true};if(empty!=null)empty.Visibility=Visibility.Collapsed;cards.Children.Insert(index,slot);Fx.Grow(slot,ghost.Height+12,0,220);};
