    var drop=new Border{Child=dock,Background=Brushes.Transparent,CornerRadius=new CornerRadius(14),Padding=new Thickness(4,7,0,0),AllowDrop=true};closeSlots+=()=>{drop.Background=Brushes.Transparent;closeSlot();};drop.DragEnter+=delegate{drop.Background=UI.B("#F0F3EA");openSlot();};drop.DragLeave+=(s,e)=>{var at=e.GetPosition(drop);if(at.X>=0&&at.Y>=0&&at.X<drop.ActualWidth&&at.Y<drop.ActualHeight)return;drop.Background=Brushes.Transparent;closeSlot();};// Обработчики с handledEventsToo: поле быстрого ввода внутри колонки иначе «съедает» перетаскивание.
    drop.AddHandler(DragOverEvent,new DragEventHandler((s,e)=>{e.Effects=e.Data.GetDataPresent(TaskFormat)?DragDropEffects.Move:DragDropEffects.None;e.Handled=true;}),true);drop.AddHandler(DropEvent,new DragEventHandler((s,e)=>{drop.Background=Brushes.Transparent;string id=e.Data.GetData(TaskFormat) as string;var task=Tasks.FirstOrDefault(t=>t.id==id);if(task!=null&&task.status!=status){task.status=status;task.completed=status=="done";landingId=task.id;if(Persist(task)&&status=="done")Celebrate(task);}else closeSlot();e.Handled=true;}),true);Grid.SetColumn(drop,i*2);grid.Children.Add(drop);}
