   check.Click+=delegate{Complete(task,card,check,check.IsChecked==true);};AttachDrag(card,task,()=>Edit(task));card.ContextMenu=TaskMenu(task);Appear(card);return card;}
  WrapPanel Chips(TaskItem t,bool withStatus){var w=new WrapPanel();string today=UI.Date(DateTime.Today);
   if(store.IsTeamName(t.category)){if(t.assignee!=null)w.Children.Add(PersonChip(t));else if(!t.completed)w.Children.Add(Fx.Chip("Не назначена",UI.Muted,UI.Rail,"\uE77B"));}
