  static bool FromControl(object source,DependencyObject stop){var d=source as DependencyObject;while(d!=null&&d!=stop){if(d is ButtonBase)return true;d=d is Visual?VisualTreeHelper.GetParent(d):LogicalTreeHelper.GetParent(d);}return false;}
  void AttachDrag(FrameworkElement element,TaskItem task,Action click){Point start=new Point();bool dragging=false,armed=false;cardsById[task.id]=element;if(task.id==landingId){landingOpacity=element.Opacity;element.Opacity=0;}element.PreviewMouseLeftButtonDown+=(s,e)=>{start=e.GetPosition(element);dragging=false;armed=!FromControl(e.OriginalSource,element);};element.PreviewMouseMove+=(s,e)=>{if(!armed||e.LeftButton!=MouseButtonState.Pressed||dragging)return;Point pos=e.GetPosition(element);if(Math.Abs(pos.X-start.X)>SystemParameters.MinimumHorizontalDragDistance||Math.Abs(pos.Y-start.Y)>SystemParameters.MinimumVerticalDragDistance){dragging=true;BeginDrag(element,task,start);e.Handled=true;}};element.MouseLeftButtonUp+=(s,e)=>{if(armed&&!dragging&&!FromControl(e.OriginalSource,element)){click();e.Handled=true;}};}
  FrameworkElement GhostFace(FrameworkElement source,TaskItem task){if(source is Border)return TaskCard(task,true);var text=UI.Text(task.title,10,UI.Ink);text.TextWrapping=TextWrapping.NoWrap;text.TextTrimming=TextTrimming.CharacterEllipsis;return new Border{Child=text,Background=UI.B("#E9EDE1"),BorderBrush=UI.B(UI.ColorFor(task.category)),BorderThickness=new Thickness(3,0,0,0),CornerRadius=new CornerRadius(9),Padding=new Thickness(6,5,5,5)};}
  // Порядок карточек: сначала выбранная сортировка, затем приоритет, срок и время создания.
  int Order(TaskItem a,TaskItem b){int c=a.completed.CompareTo(b.completed);if(c!=0)return c;switch(store.Settings.TaskSort){case 1:c=string.CompareOrdinal(a.date??"9999",b.date??"9999");break;case 2:c=PersonRank(a).CompareTo(PersonRank(b));if(c==0)c=string.Compare(a.assignee??"",b.assignee??"",StringComparison.CurrentCultureIgnoreCase);break;case 3:c=string.Compare(a.title,b.title,StringComparison.CurrentCultureIgnoreCase);break;case 4:c=b.createdAt.CompareTo(a.createdAt);break;}if(c==0)c=a.priority.CompareTo(b.priority);if(c==0)c=string.CompareOrdinal(a.date??"9999",b.date??"9999");if(c==0)c=a.createdAt.CompareTo(b.createdAt);return c;}
  int PersonRank(TaskItem t){return store.IsMine(t)?0:t.assignee==null?2:1;}
  [StructLayout(LayoutKind.Sequential)] struct CursorPoint{public int X,Y;}
  [DllImport("user32.dll")] static extern bool GetCursorPos(out CursorPoint point);
  // Перетаскивание: карточка-источник бледнеет, «призрак» следует за курсором, затем садится на новое место (или возвращается назад).
  void BeginDrag(FrameworkElement element,TaskItem task,Point grab){
   element.BeginAnimation(UIElement.OpacityProperty,null);double was=element.Opacity;dragTask=task;landingId=null;
   try{ghost=new DragGhost(dragLayer,element,GhostFace(element,task),grab,element.TranslatePoint(grab,dragLayer));}catch{ghost=null;}
   if(Fx.Enabled)element.BeginAnimation(UIElement.OpacityProperty,Fx.A(null,.22,160));else element.Opacity=.3;
   GiveFeedbackEventHandler feedback=(s,e)=>{CursorPoint p;if(ghost!=null&&GetCursorPos(out p))ghost.Follow(dragLayer.PointFromScreen(new Point(p.X,p.Y)));e.UseDefaultCursors=false;Mouse.SetCursor(e.Effects==DragDropEffects.None?Cursors.No:Cursors.Hand);e.Handled=true;};
   element.GiveFeedback+=feedback;
   try{DragDrop.DoDragDrop(element,new DataObject(TaskFormat,task.id),DragDropEffects.Move);}finally{element.GiveFeedback-=feedback;dragTask=null;if(landingId==null&&closeSlots!=null)closeSlots();}
   var flying=ghost;ghost=null;
   Action restore=()=>{if(Fx.Enabled){var back=Fx.A(null,was,260);back.Completed+=delegate{element.BeginAnimation(UIElement.OpacityProperty,null);element.Opacity=was;};element.BeginAnimation(UIElement.OpacityProperty,back);}else{element.BeginAnimation(UIElement.OpacityProperty,null);element.Opacity=was;}};
   if(landingId!=null){string id=landingId;Dispatcher.BeginInvoke(DispatcherPriority.Loaded,new Action(()=>{FrameworkElement target;double to=landingOpacity;landingId=null;if(cardsById.TryGetValue(id,out target)&&PresentationSource.FromVisual(target)!=null){if(flying!=null)flying.Land(target.TranslatePoint(new Point(0,0),dragLayer),()=>target.Opacity=to);else target.Opacity=to;}else{if(flying!=null)flying.Vanish();if(target!=null)target.Opacity=to;}}));}
   else if(PresentationSource.FromVisual(element)!=null){if(flying!=null)flying.Land(element.TranslatePoint(new Point(0,0),dragLayer),()=>{});restore();}
   else if(flying!=null)flying.Vanish();
  }
  ContextMenu TaskMenu(TaskItem task){var m=new ContextMenu();Func<string,string,Action,MenuItem> add=(glyph,text,act)=>{var i=new MenuItem{Header=text,Icon=UI.Icon(glyph,12,UI.Muted)};i.Click+=delegate{act();};m.Items.Add(i);return i;};
   add("","Открыть",()=>Edit(task));m.Items.Add(new Separator());
   foreach(var pair in new[]{new[]{"todo","К выполнению",""},new[]{"doing","В работе",""},new[]{"done","Готово",""}}){string state=pair[0];var item=add(pair[2],pair[1],()=>{var t=task.Clone();t.status=state;t.completed=state=="done";if(Persist(t)&&state=="done")Celebrate(t);});item.IsEnabled=task.status!=state;}
   m.Items.Add(new Separator());add("","На сегодня",()=>Reschedule(task,DateTime.Today));add("","На завтра",()=>Reschedule(task,DateTime.Today.AddDays(1)));add("","Через неделю",()=>Reschedule(task,DateTime.Today.AddDays(7)));if(task.date!=null)add("","Убрать дату",()=>Reschedule(task,null));
   if(store.IsTeamName(task.category)){m.Items.Add(new Separator());var assign=new MenuItem{Header="Исполнитель",Icon=UI.Icon("\uE77B",12,UI.Muted)};string me=store.Me(task.category);Action<string,string> pick=(label,name)=>{var i=new MenuItem{Header=label,IsChecked=name==null?task.assignee==null:Store.SamePerson(task.assignee,name)};i.Click+=delegate{Assign(task,name);};assign.Items.Add(i);};pick(me+" (вы)",me);foreach(var n in store.Members(task.category).Where(n=>!Store.SamePerson(n,me)))pick(n,n);assign.Items.Add(new Separator());pick("Без исполнителя",null);m.Items.Add(assign);}
   m.Items.Add(new Separator());add("","Дублировать",()=>Duplicate(task));add("","Удалить",()=>RemoveTask(task));return m;}
  void Complete(TaskItem task,UIElement visual,UIElement check,bool done){var before=task.Clone();var t=task.Clone();t.completed=done;t.status=done?"done":"todo";Action commit=()=>{if(!Persist(t))return;if(done&&!Celebrate(t))Toast("Выполнено: «"+Short(t.title)+"»","Отменить",()=>Restore(before));};if(done&&Fx.Enabled){Fx.Pop(check,.6);var wait=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(160)};wait.Tick+=delegate{wait.Stop();Fx.FadeOut(visual,commit,.25,230);};wait.Start();}else commit();}
  void Restore(TaskItem before){var fresh=Tasks.FirstOrDefault(x=>x.id==before.id);if(fresh==null)return;fresh.status=before.status;fresh.completed=before.completed;fresh.date=before.date;Persist(fresh);}
  bool Celebrate(TaskItem t){string today=UI.Date(DateTime.Today);if(t.date==null||string.CompareOrdinal(t.date,today)>0)return false;var all=Tasks.Where(store.IsMine).ToList();if(all.Any(x=>!x.completed&&x.date!=null&&string.CompareOrdinal(x.date,today)<=0)||!all.Any(x=>x.date==today))return false;Toast("Все дела на сегодня закрыты — отличная работа!",null,null,6);return true;}
  void Reschedule(TaskItem task,DateTime? day){var t=task.Clone();t.date=day.HasValue?UI.Date(day.Value):null;if(Persist(t))Toast("«"+Short(t.title)+"» → "+UI.FriendlyDate(t.date).ToLower(ru));}
  void Duplicate(TaskItem task){try{var copy=task.Clone();copy.id=Guid.NewGuid().ToString();copy.version=0;copy.createdAt=0;copy.updatedUtc=null;copy.deviceId=null;copy.completed=false;if(copy.status=="done")copy.status="todo";copy.title=(copy.title.Length>190?copy.title.Substring(0,190):copy.title)+" (копия)";foreach(var s in copy.subtasks){s.id=Guid.NewGuid().ToString();s.done=false;}store.Save(copy,0);Refresh();RunCloudSync();Toast("Создана копия задачи");}catch(Exception e){Error(e);}}
  void RemoveTask(TaskItem task){try{store.Delete(task);Refresh();RunCloudSync();Toast("Задача «"+Short(task.title)+"» удалена","Отменить",()=>{try{var back=task.Clone();back.id=Guid.NewGuid().ToString();back.version=0;back.updatedUtc=null;back.deviceId=null;back.deleted=false;store.Save(back,0);Refresh();RunCloudSync();}catch(Exception e){Error(e);}},7);}catch(Exception e){Error(e);}}
  // ——— Список ———
  static readonly string[] buckets={"Просрочено","Сегодня","Завтра","Ближайшие 7 дней","Позже","Без даты","Выполнено"};
  static int Bucket(TaskItem t){if(t.completed)return 6;if(t.date==null)return 5;var d=DateTime.ParseExact(t.date,"yyyy-MM-dd",CultureInfo.InvariantCulture);int diff=(d-DateTime.Today).Days;return diff<0?0:diff==0?1:diff==1?2:diff<=7?3:4;}
  UIElement List(List<TaskItem> tasks){var p=new StackPanel{Margin=new Thickness(0,0,8,0)};if(view!="today"){var quick=QuickAdd("todo");p.Children.Add(quick);}
   if(tasks.Count==0)p.Children.Add(Empty("Пока нет задач","Добавьте первую задачу или измените фильтры."));
   bool first=true;foreach(var group in tasks.GroupBy(Bucket).OrderBy(g=>g.Key)){var header=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(4,first?4:20,0,10)};first=false;header.Children.Add(UI.Text(buckets[group.Key],12,group.Key==0?Fx.Solid("#E5484D"):UI.Ink,true));var n=UI.Text(group.Count().ToString(),11,UI.Muted);n.Margin=new Thickness(8,0,0,0);header.Children.Add(n);p.Children.Add(header);Appear(header);foreach(var task in group)p.Children.Add(TaskRow(task));}
   return new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};}
  UIElement TaskRow(TaskItem task){var row=new DockPanel();var check=new CheckBox{IsChecked=task.completed,Margin=new Thickness(0,0,14,0),VerticalAlignment=VerticalAlignment.Center};System.Windows.Automation.AutomationProperties.SetName(check,"Выполнить: "+task.title);DockPanel.SetDock(check,Dock.Left);row.Children.Add(check);
