  void UpdateFocus(){UpdateTaskbar();if(focusClock==null)return;int seconds=focus.Remaining;bool brk=focus.State.Mode=="break",running=focus.State.Running;focusClock.Text=(seconds/60).ToString("00")+":"+(seconds%60).ToString("00");focusInfo.Text=running?(brk?"перерыв":"фокус"):seconds<focus.Duration?"на паузе":brk?"время отдохнуть":"готов к работе";focusToggle.Content=running?"Пауза":seconds<focus.Duration?"Продолжить":"Начать";focusArc.Data=Fx.Arc(180,10,1.0-seconds/(double)focus.Duration);focusArc.Stroke=brk?UI.B("#29938B"):UI.Accent;focusSessions.Text=focus.State.Sessions==0?"":"сессий: "+focus.State.Sessions;Select(focusModeButton,!brk);Select(breakModeButton,brk);}
  void UpdateTaskbar(){var info=TaskbarItemInfo;if(info==null)return;int s=focus.Remaining;double v=1.0-s/(double)focus.Duration;info.ProgressValue=v;if(focus.State.Running){info.ProgressState=TaskbarItemProgressState.Normal;Title=(s/60).ToString("00")+":"+(s%60).ToString("00")+" · "+(focus.State.Mode=="break"?"перерыв":"фокус")+" · Ритм";}else{info.ProgressState=v>0&&v<1?TaskbarItemProgressState.Paused:TaskbarItemProgressState.None;Title="Ритм";}}
  void FocusEnded(){try{System.Media.SystemSounds.Asterisk.Play();}catch{}var task=Tasks.FirstOrDefault(t=>t.id==store.Settings.FocusTaskId);bool rest=focus.State.Mode=="break";Toast(rest?"Сессия фокуса завершена"+(task!=null?" · «"+Short(task.title)+"»":"")+". Пора отдохнуть 5 минут.":"Перерыв окончен. Продолжим?",rest?"Перерыв":"Начать фокус",()=>{focus.Start();store.SaveLocalPreferences();UpdateFocus();},12);if(!IsActive)Flash();}
  [StructLayout(LayoutKind.Sequential)] struct FlashInfo{public uint cbSize;public IntPtr hwnd;public uint dwFlags,uCount,dwTimeout;}
  [DllImport("user32.dll")] static extern bool FlashWindowEx(ref FlashInfo info);
  void Flash(){try{var info=new FlashInfo{hwnd=new WindowInteropHelper(this).Handle,dwFlags=3|12,uCount=5};info.cbSize=(uint)Marshal.SizeOf(info);FlashWindowEx(ref info);}catch{}}
  string LayoutContext{get{return project!=""?"project:"+project:view=="board"||view=="list"?"tab:tasks":"tab:"+view;}}
  string CurrentTaskLayout{get{return store.GetTaskLayout(LayoutContext,view=="today"||view=="list"?"list":"board");}}
  void SetTaskLayout(string mode){store.SetTaskLayout(LayoutContext,mode);if(project==""&&(view=="board"||view=="list"))view=mode;Refresh();}
  void UpdateLayoutButtons(){layoutSwitch.Visibility=view=="calendar"?Visibility.Collapsed:Visibility.Visible;foreach(var button in new[]{boardLayoutButton,listLayoutButton}){bool on=button==(CurrentTaskLayout=="board"?boardLayoutButton:listLayoutButton);Select(button,on);button.ToolTip=on?"Текущий вид задач":"Показать задачи: "+System.Windows.Automation.AutomationProperties.GetName(button);}}
  public void PreviewView(string name){view=name;Refresh();}
  public void PreviewTaskLayout(string layout,string projectName=null){if(projectName!=null)Go("board",projectName);SetTaskLayout(layout);}
 }
